namespace sv_c3bf48cef5ea49fb837ed6a00ab1af89.Models;

public record JobApplication(PersonalInfo Personal, WorkHistory Work, List<Reference> References, string CoverLetter);
public record PersonalInfo(string FullName, string Email, string Phone, string Address);
public record WorkHistory(List<WorkEntry> Entries);
public record WorkEntry(string Company, string Title, DateTime StartDate, DateTime? EndDate, string Description);
public record Reference(string Name, string Relationship, string Email, string Phone);

public interface IApplicationService
{
    Task<int> SubmitApplicationAsync(JobApplication application);
    Task<bool> ValidateEmailAsync(string email);
}

/// <summary>
/// Mutable form models used during editing, converted to records on submit.
/// </summary>
public class PersonalInfoModel
{
    public string FullName { get; set; } = "";
    public string Email { get; set; } = "";
    public string Phone { get; set; } = "";
    public string Address { get; set; } = "";

    public bool IsValid() =>
        !string.IsNullOrWhiteSpace(FullName) &&
        !string.IsNullOrWhiteSpace(Email) &&
        !string.IsNullOrWhiteSpace(Phone) &&
        !string.IsNullOrWhiteSpace(Address);

    public PersonalInfo ToRecord() => new(FullName, Email, Phone, Address);
}

public class WorkEntryModel
{
    public string Company { get; set; } = "";
    public string Title { get; set; } = "";
    public DateTime StartDate { get; set; } = DateTime.Today;
    public DateTime? EndDate { get; set; } = DateTime.Today;
    public bool IsCurrent { get; set; }
    public string Description { get; set; } = "";

    public bool IsValid() =>
        !string.IsNullOrWhiteSpace(Company) &&
        !string.IsNullOrWhiteSpace(Title);

    public WorkEntry ToRecord() => new(Company, Title, StartDate, IsCurrent ? null : EndDate, Description);
}

public class ReferenceModel
{
    public string Name { get; set; } = "";
    public string Relationship { get; set; } = "";
    public string Email { get; set; } = "";
    public string Phone { get; set; } = "";

    public bool IsValid() =>
        !string.IsNullOrWhiteSpace(Name) &&
        !string.IsNullOrWhiteSpace(Relationship) &&
        !string.IsNullOrWhiteSpace(Email) &&
        !string.IsNullOrWhiteSpace(Phone);

    public Reference ToRecord() => new(Name, Relationship, Email, Phone);
}

@namespace sv_c3bf48cef5ea49fb837ed6a00ab1af89.Components.Pages.Apply

<nav class="d-flex justify-content-between align-items-center mb-4 p-3 bg-light rounded">
    @for (int i = 0; i < StepNames.Count; i++)
    {
        var stepIndex = i;
        var isCurrent = stepIndex == CurrentStep;
        var isCompleted = stepIndex < CurrentStep;
        var isFuture = stepIndex > CurrentStep;

        <div class="text-center flex-fill position-relative">
            @if (stepIndex > 0)
            {
                <div class="position-absolute top-50 start-0 translate-middle-y"
                     style="width:50%; height:2px; left:0;"
                     class="@(isCompleted || isCurrent ? "bg-primary" : "bg-secondary opacity-25")">
                </div>
            }

            <button type="button"
                    class="btn rounded-circle p-0 d-inline-flex align-items-center justify-content-center @StepButtonClass(stepIndex)"
                    style="width:36px; height:36px; font-size:0.85rem;"
                    disabled="@isFuture"
                    @onclick="() => OnStepClicked.InvokeAsync(stepIndex)">
                @if (isCompleted)
                {
                    <span>✓</span>
                }
                else
                {
                    <span>@(stepIndex + 1)</span>
                }
            </button>
            <div class="small mt-1 @(isFuture ? "text-muted" : isCurrent ? "fw-bold text-primary" : "text-success")">
                @StepNames[stepIndex]
            </div>
        </div>
    }
</nav>

@code {
    [Parameter, EditorRequired] public int CurrentStep { get; set; }
    [Parameter, EditorRequired] public EventCallback<int> OnStepClicked { get; set; }

    private static readonly List<string> StepNames =
    [
        "Personal Info",
        "Work History",
        "References",
        "Cover Letter",
        "Review & Submit"
    ];

    private string StepButtonClass(int step)
    {
        if (step == CurrentStep) return "btn-primary";
        if (step < CurrentStep) return "btn-success";
        return "btn-outline-secondary";
    }
}

@namespace sv_c3bf48cef5ea49fb837ed6a00ab1af89.Components.Pages.Apply
@using sv_c3bf48cef5ea49fb837ed6a00ab1af89.Models

<div class="card mb-3">
    <div class="card-body">
        <div class="d-flex justify-content-between align-items-center mb-3">
            <h6 class="card-title mb-0">Reference @(Index + 1)</h6>
            @if (CanRemove)
            {
                <button type="button" class="btn btn-outline-danger btn-sm" @onclick="OnRemove">Remove</button>
            }
        </div>

        <div class="row g-3">
            <div class="col-md-6">
                <label class="form-label">Name</label>
                <input type="text" class="form-control" @bind="Reference.Name" />
            </div>
            <div class="col-md-6">
                <label class="form-label">Relationship</label>
                <input type="text" class="form-control" @bind="Reference.Relationship" />
            </div>
            <div class="col-md-6">
                <label class="form-label">Email</label>
                <input type="email" class="form-control" @bind="Reference.Email" />
            </div>
            <div class="col-md-6">
                <label class="form-label">Phone</label>
                <input type="tel" class="form-control" @bind="Reference.Phone" />
            </div>
        </div>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public ReferenceModel Reference { get; set; } = default!;
    [Parameter] public int Index { get; set; }
    [Parameter] public bool CanRemove { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }
}

