@namespace sv_c3bf48cef5ea49fb837ed6a00ab1af89.Components.Pages.Apply

<nav class="d-flex justify-content-between align-items-center mb-4 p-3 bg-light rounded">
    @for (int i = 0; i < StepNames.Count; i++)
    {
        var stepIndex = i;
        var isCurrent = stepIndex == CurrentStep;
        var isCompleted = stepIndex < CurrentStep;
        var isFuture = stepIndex > CurrentStep;

        <div class="text-center flex-fill position-relative">
            @if (stepIndex > 0)
            {
                <div class="position-absolute top-50 start-0 translate-middle-y"
                     style="width:50%; height:2px; left:0;"
                     class="@(isCompleted || isCurrent ? "bg-primary" : "bg-secondary opacity-25")">
                </div>
            }

            <button type="button"
                    class="btn rounded-circle p-0 d-inline-flex align-items-center justify-content-center @StepButtonClass(stepIndex)"
                    style="width:36px; height:36px; font-size:0.85rem;"
                    disabled="@isFuture"
                    @onclick="() => OnStepClicked.InvokeAsync(stepIndex)">
                @if (isCompleted)
                {
                    <span>✓</span>
                }
                else
                {
                    <span>@(stepIndex + 1)</span>
                }
            </button>
            <div class="small mt-1 @(isFuture ? "text-muted" : isCurrent ? "fw-bold text-primary" : "text-success")">
                @StepNames[stepIndex]
            </div>
        </div>
    }
</nav>

@code {
    [Parameter, EditorRequired] public int CurrentStep { get; set; }
    [Parameter, EditorRequired] public EventCallback<int> OnStepClicked { get; set; }

    private static readonly List<string> StepNames =
    [
        "Personal Info",
        "Work History",
        "References",
        "Cover Letter",
        "Review & Submit"
    ];

    private string StepButtonClass(int step)
    {
        if (step == CurrentStep) return "btn-primary";
        if (step < CurrentStep) return "btn-success";
        return "btn-outline-secondary";
    }
}

